CREATE TABLE shipment (shipment_id int, weight_kg numeric(8,2), carrier text);
INSERT INTO shipment VALUES (1, 10.5, 'A'), (2, NULL, 'A'), (2, 4.0, 'B'), (3, NULL, 'B'), (4, 7.2, 'A'), (4, 7.2, 'A'), (4, 7.2, 'A');
SELECT check_name, violations FROM (
  SELECT 'duplicate shipment_id' AS check_name, count(*) AS violations
  FROM (SELECT shipment_id FROM shipment GROUP BY shipment_id HAVING count(*) > 1) d
  UNION ALL
  SELECT 'missing weight', count(*) FROM shipment WHERE weight_kg IS NULL
) checks
ORDER BY check_name;

