import hashlib
import sqlite3
from decimal import Decimal

rows = [(1, "high", "120.00"), (2, "low", "35.50"), (3, "low", "20.00"), (4, "high", "99.99"), (5, "mid", "60.00")]
stats = {"read": 7, "rejected": 2, "rows": rows}

def build(rows):
    conn = sqlite3.connect(":memory:")
    conn.execute("CREATE TABLE ticket (ticket_id INTEGER PRIMARY KEY, priority TEXT, cost_cents INTEGER)")
    conn.executemany("INSERT INTO ticket VALUES (?, ?, ?)", [(i, p, int(Decimal(c) * 100)) for i, p, c in rows])
    return conn

def validate_load(conn, stats):
    loaded = conn.execute("SELECT ticket_id, priority, cost_cents FROM ticket").fetchall()
    want = [(i, p, int(Decimal(c) * 100)) for i, p, c in stats["rows"]]
    def per_group(items):
        counts = {}
        for _, p, _ in items:
            counts[p] = counts.get(p, 0) + 1
        return counts
    def digest(items):
        return hashlib.md5(",".join(f"{i}|{p}|{c}" for i, p, c in sorted(items)).encode()).hexdigest()
    checks = [
        ("reconcile", stats["read"] == len(loaded) + stats["rejected"]),
        ("control total", sum(c for _, _, c in loaded) == sum(c for _, _, c in want)),
        ("per priority", per_group(loaded) == per_group(want)),
        ("row hash", digest(loaded) == digest(want)),
    ]
    return [f"{name}: {'PASS' if ok else 'FAIL'}" for name, ok in checks]

good = build(rows)
for line in validate_load(good, stats):
    print(line)
bad = build(rows)
with bad:
    bad.execute("UPDATE ticket SET priority = 'high' WHERE ticket_id = 3")
for line in validate_load(bad, stats):
    print(line)

